'use strict';
const $ = (q) => document.querySelector(q);
const esc = (x) => String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const subjects=['Quant','Verbal','DI'];
const prices={1:10000,2:18000,3:25000};
const money=n=>'₹'+n.toLocaleString('en-IN');
const state=()=>({screen:'catalogue',role:'student',route:'recordings',tier:1,selected:['Quant'],owned:['Quant','Verbal','DI'],subject:'Quant',locked:false,session:4,reading:false,expired:false,modal:'',date:'2026-11-05',time:'18:00',eventType:'live',published:false,feedback:'due',offering:'Full Course',title:'Before class: Ratios and mixtures',post:'After class: Ratio practice and recap'});
let s=state();
const scenarios=[
 ['catalogue','01 · Recordings: choose your subjects',{screen:'catalogue'}],
 ['package','02 · Two-subject package',{screen:'catalogue',tier:2,selected:['Quant','Verbal']}],
 ['live-catalogue','03 · Live courses: pricing and public schedule',{screen:'catalogue',route:'live',tier:3,selected:subjects}],
 ['detail','04 · Detailed outline and sample session',{screen:'detail'}],
 ['learning','05 · Pick up where you left off',{screen:'learning'}],
 ['locked','06 · Quant feedback due; other subjects available',{screen:'learning',locked:true}],
 ['upsell','07 · Locked section: upgrade pop-up',{screen:'learning',owned:['Quant'],modal:'upsell',upgrade:'Verbal'}],
 ['live-student','08 · Your enrolled live classes',{screen:'live',route:'live'}],
 ['session','09 · Four ordered session items',{screen:'session'}],
 ['reading','10 · Pre-class reading expanded',{screen:'session',reading:true}],
 ['feedback','11 · Feedback and current session access',{screen:'feedback',locked:true,route:'live'}],
 ['pending','12 · Feedback awaiting secure confirmation',{screen:'feedback',locked:true,feedback:'pending'}],
 ['expired','13 · Membership expired; history retained',{screen:'expired',expired:true}],
 ['editor','14 · Admin: session configuration',{screen:'editor',role:'admin'}],
 ['batch','15 · Admin: batch publishing',{screen:'batch',role:'admin'}],
 ['calendar','16 · Calendar pop-up for an actual live class',{screen:'batch',role:'admin',modal:'calendar'}],
 ['scope','17 · Confirm publication scope',{screen:'scope',role:'admin'}],
 ['decisions','18 · Design decisions and implementation boundaries',{screen:'decisions'}]
];
const action=(label,key,primary=false,attrs='')=>`<button data-action="${key}" class="${primary?'primary':''}" ${attrs}>${label}</button>`;
const goButton=(label,key,primary=false)=>`<button data-screen="${key}" class="${primary?'primary':''}">${label}</button>`;
const pill=(label,kind='')=>`<span class="pill ${kind}">${label}</span>`;
const heading=(tag,title,body,aside='')=>`<div class="heading"><div><div class="eyebrow">${tag}</div><h1>${title}</h1><p class="muted">${body}</p></div>${aside}</div>`;
const note=text=>`<p class="annotation">Design review · ${text}</p>`;
function nav(){const admin=s.role==='admin';return `<aside class="sidebar"><div class="brand"><b>a.</b>Ace Club</div><div class="nav-label">${admin?'Course publishing':'Your workspace'}</div><nav aria-label="Primary">${(admin?[['editor','Session configuration'],['batch','Batch publishing']]:[['learning','My learning'],['live','Live classes'],['catalogue','Explore courses'],[s.expired?'expired':'access','My access']]).map(([key,label])=>`<button data-screen="${key}" class="${s.screen===key?'active':''}">${label}</button>`).join('')}</nav><div class="nav-label">${admin?'Other areas':'Practice'}</div><nav>${action('Mocks · unchanged','mocks')}</nav><div class="persona">${admin?'Demo Admin':'Demo student'}<br><small>Fictional review account</small></div></aside>`;}
function routeTabs(){return `<div class="tabs route-tabs" aria-label="Learning route"><button data-route="recordings" class="${s.route==='recordings'?'active':''}"><strong>Recordings</strong><small>Learn at your pace · choose any available session</small></button><button data-route="live" class="${s.route==='live'?'active':''}"><strong>Live courses</strong><small>Learn with your batch · view the published schedule</small></button></div>`;}
function schedule(publicView=true){return `<div class="row between"><h2>${publicView?'Published live schedule':'November evening · your enrolled batch'}</h2>${pill(publicView?'Preview before payment':'Active registration')}</div><table class="table"><thead><tr><th>Subject / live class</th><th>Date & time · IST</th><th>${publicView?'Availability':'Join'}</th></tr></thead><tbody>${[['Quant','Ratios and mixtures','5 Nov · 6:00–7:30 PM','6 / 8 registered'],['Verbal','Argument structure','7 Nov · 6:00–7:30 PM','5 / 8 registered'],['DI','Reading tables','9 Nov · 6:00–7:30 PM','8 / 8 · Closed']].filter(([sub])=>publicView||sub==='Quant').map(([sub,name,date,capacity])=>`<tr><td><strong>${sub}</strong><br>${name}</td><td>${date}</td><td>${publicView?capacity:sub==='Quant'?action('Join class · demo','meet',true):'Not enrolled in this live batch'}</td></tr>`).join('')}</tbody></table><small>${publicView?'Only actual live classes have dates. No Meet links before eligible registration. No waitlist or session reservation.':'Only your eligible live registration exposes a join action. Course access alone is not live registration.'}</small>`;}
function catalogue(){const enough=s.selected.length===s.tier;return heading('Explore courses','Choose how you learn. Then choose your subjects.','The complete curriculum, with a package that fits your plan.')+routeTabs()+`<div class="grid three">${[1,2,3].map(n=>`<button class="tier ${s.tier===n?'active':''}" data-tier="${n}" aria-pressed="${s.tier===n}">${pill(n===1?'ONE SUBJECT':n===2?'TWO SUBJECTS':'THREE SUBJECTS',n===s.tier?'':'gray')}<h2>${n===1?'Build one strength':n===2?'Connect two subjects':'Cover all three subjects'}</h2><div class="price">${money(prices[n])}</div><small>${n===1?'₹10,000 per subject':n===2?'₹9,000 per subject':'About ₹8,333 per subject'} · total package price above</small></button>`).join('')}</div><section class="card space"><div class="row between"><div><h2>Choose ${s.tier===1?'one subject':s.tier+' subjects'}</h2><small>${s.selected.length} of ${s.tier} selected · complete individual curricula</small></div>${pill(s.route==='live'?'Live-course package':'Recordings package')}</div><div class="selection">${subjects.map(x=>`<label class="choice"><input type="checkbox" data-subject-choice="${x}" ${s.selected.includes(x)?'checked':''}> ${x}</label>`).join('')}</div><div class="row between"><div><strong>${enough?s.selected.join(' + '):'Select '+s.tier+' subjects to continue'}</strong><p class="muted">Six calendar months of access from successful payment.</p></div>${action('Review '+(enough?money(prices[s.tier]):'package'),'review-package',true,enough?'':'disabled')}</div></section><section class="full-option"><div><strong>Looking for Full Course?</strong><p>One distinct offering: Quant + Verbal + DI together.</p><small>Three individual subjects stay an individual package; they do not become Full Course.</small></div><strong>${money(25000)}</strong>${action('Explore Full Course','full-course')}</section>${s.route==='live'?`<section class="card space">${schedule()}</section>`:''}`+note('Illustrative prices from the approved package model. Purchases and live registration are not connected in this prototype.');}
function detail(){const list=s.offering==='Full Course'?subjects:s.selected;return heading(s.route==='live'?'Live-course outline':'Recordings outline',esc(s.offering),list.join(' + ')+' · Six months from successful payment',goButton('Back to courses','catalogue'))+`<div class="grid split"><section class="card"><h2>A detailed course outline</h2><div class="outline">${list.map(sub=>`<details open><summary>${sub}</summary><ul>${(sub==='Quant'?['Number foundations · Fractions and ratios','Mixtures · Percentages','Algebra · Word problems']:sub==='Verbal'?['Reading comprehension · main idea and inference','Critical reasoning · assumptions and strengthen/weaken','Passage analysis · evidence and structure']:['Tables and charts · interpretation','Data sufficiency · reasoning','Multi-source reasoning · practice']).map(x=>`<li>${x}</li>`).join('')}</ul></details>`).join('')}</div><div class="space"><h3>Preview one session</h3><p>Ratios and mixtures: a sample of the four resources in every session.</p><div class="status-list"><span>01 Pre-class read</span><span>02 Recording</span><span>03 Post-class read</span><span>04 Worksheet</span></div>${action('Open sample session','sample-session')}</div></section><aside class="card"><h2>${s.offering==='Full Course'?'Full Course':s.selected.length+'-subject package'}</h2><div class="price">${money(s.upgradeQuote?s.upgradeQuote.difference:s.offering==='Full Course'?25000:prices[s.selected.length])}</div>${s.upgradeQuote?`<strong>Upgrade difference · illustrative</strong><p>Existing package ${money(s.upgradeQuote.existing)} → new package ${money(s.upgradeQuote.total)}. Pay only the ${money(s.upgradeQuote.difference)} difference after server eligibility verification.</p>`:''}<p>Full access to the selected curriculum for six calendar months.</p><div class="notice"><strong>${s.route==='live'?'Check batch availability':'Learn in your own order'}</strong><p>${s.route==='live'?'Live registration closes at eight registered students per live course.':'Sessions need no dates. Recordings access does not include private Meet details.'}</p></div><div class="space">${action('Continue · design demo','checkout',true)}</div></aside></div>${s.route==='live'?`<section class="card space">${schedule()}</section>`:''}`+note('The sample is fictional preview content, not an exception that exposes paid recordings.');}
const topics={Quant:['Number foundations','Fractions and ratios','Mixtures','Ratios and mixtures','Percentages'],Verbal:['Reading with purpose','Argument structure','Inference practice','Critical reasoning','Passage analysis'],DI:['Reading tables','Chart interpretation','Data comparison','Multi-source reasoning','Case practice']};
function learning(){const locked=s.locked&&s.subject==='Quant';const current=s.subject==='Quant'?4:1;return heading('My learning',s.subject+' · Your course','Choose any published session. The highlight shows your last opened session, not a completion score.',pill('Access active'))+`<div class="tabs" aria-label="Subjects">${subjects.map(x=>`<button data-subject="${x}" class="${x===s.subject?'active':''}" aria-pressed="${x===s.subject}">${x}${!s.owned.includes(x)?' · Locked':s.locked&&x==='Quant'?' · Feedback due':''}</button>`).join('')}</div>${locked?`<section class="feedback-banner"><div class="eyebrow">Quant feedback required</div><h2>A moment of feedback. Then keep learning.</h2><p>Other Quant sessions are paused until your Quant 4 feedback is securely confirmed. Quant 4 readings, recording and worksheet remain open. Your purchased Verbal and DI sections stay available.</p><div class="row">${goButton('Give Quant 4 feedback','feedback',true)}${action('Open current session','resume')}</div></section>`:`<section class="resume-banner"><div class="row between"><div><div class="eyebrow"><span class="resume-dot"></span>Pick up where you left off</div><h2>${s.subject} ${current} · ${topics[s.subject][current-1]}</h2><p>Last opened: pre-class read · visual reminder only</p></div>${action('Resume session →','resume',true)}</div></section>`}<div class="row between"><h2>Your sessions</h2><a href="#outline" data-action="outline">View outline highlights</a></div><div class="session-list">${topics[s.subject].map((x,i)=>{const n=i+1;const block=locked&&n!==4;return `<article class="session-row ${block?'locked':n===current?'resume':''}"><span class="number">${String(n).padStart(2,'0')}</span><div class="grow"><h3>${x}</h3><small>${block?'Feedback required before opening':n===current?'● Last opened · resume here':'Available · choose in any order'}</small></div><button data-session="${n}" ${block?'disabled':''}>${block?'Paused':n===current?'Resume':'Open'}</button></article>`;}).join('')}<article class="session-row locked"><span class="number">06</span><div class="grow"><h3>Next session</h3><small>Not published yet</small></div><button disabled>Unavailable</button></article></div>`+note('The whole affected subject list is visually muted except the current session. Feedback does not unlock expired access or an unpurchased subject.');}
function live(){return heading('My learning / live classes','Your next live class, in one place.','Live attendance and recordings are separate routes. Learn using either, or both.')+`<section class="card">${schedule(false)}</section><section class="card space"><h2>After your live class</h2><p>Class completion, recording availability, feedback and attendance are separate states. A missed class may be reported honestly; watching a recording is not required to submit “I didn’t attend”.</p><div class="row">${goButton('Open session resources','session',true)}${goButton('View all subjects','learning')}</div></section>`+note('The demo student is registered only in the Quant live batch. Verbal/DI course entitlements do not expose their private live links.');}
function session(){const topic=topics[s.subject][s.session-1];const quantExample=s.subject==='Quant'&&s.session===4;const pre=quantExample?s.title:'Before class: '+topic;const post=quantExample?s.post:'After class: '+topic+' recap';return heading('My learning / '+s.subject,s.subject+' '+s.session+' · '+topics[s.subject][s.session-1],'Four resources, in a clear order. Open whichever you need.',goButton('All sessions','learning'))+`${s.locked?`<div class="notice warning"><strong>Quant 4 feedback is due</strong><p>This current session stays accessible while the other Quant sessions are paused.</p>${goButton('Give feedback','feedback',true)}</div>`:''}<div class="lesson"><section class="lesson-section" data-item="pre"><div class="section-label"><span class="number">01</span><div><small>PRE-CLASS READ</small><h2>${esc(pre)}</h2></div></div><details ${s.reading?'open':''}><summary>Read the preparation</summary><div class="reading">${quantExample?`<p>A ratio compares quantities in the same unit. Start by checking what each number represents.</p><blockquote>For every two parts concentrate, add three parts water. There are five equal parts altogether.</blockquote><p>A 500 ml mixture at 2:3 contains 200 ml concentrate and 300 ml water.</p><a href="#worked" data-action="worked">See the worked example</a>`:`<p>Prepare for ${esc(topic)} by reading the example and identifying the main information.</p><blockquote>${s.subject==='Verbal'?'Separate the claim from its supporting evidence. What conclusion is justified?':'Compare the data labels and units before drawing a conclusion. Which information supports your answer?'}</blockquote><p>Bring your reasoning to the guided lesson, then use the worksheet for practice.</p>`}</div></details></section><section class="lesson-section" data-item="recording"><div class="section-label"><span class="number">02</span><div><small>RECORDING</small><h2>${esc(topic)} · guided lesson</h2></div></div><div class="player"><span class="eyebrow" style="color:#d9e4d7">ONE SHARED SESSION RECORDING</span><span class="play">▶</span><small>Illustrative player · no video or tracking</small></div></section><section class="lesson-section" data-item="post"><div class="section-label"><span class="number">03</span><div><small>POST-CLASS READ</small><h2>${esc(post)}</h2></div></div><details><summary>Read the recap</summary><p>Review the main ideas from ${esc(topic)}. Use the worksheet to practise the method.</p></details></section><section class="lesson-section" data-item="worksheet"><div class="section-label"><span class="number">04</span><div><small>WORKSHEET</small><h2>${esc(topic)}: guided practice and worked answers</h2></div></div><div class="worksheet"><span class="muted">Session material · 8 practice questions</span>${action('Open worksheet','worksheet')}</div></section></div>`+note('No redundant right rail or step-navigation strip. Reading opening is visual only. The shared recording is reused across applicable offerings and batches.');}
function feedback(){const pending=s.feedback==='pending';const confirmed=s.feedback==='confirmed';return heading('Quant 4 / feedback',confirmed?'Thank you. Your Quant section is open.':pending?'Your feedback is being confirmed.':'A little feedback. Then keep learning.','One session-referenced response. Your current session resources remain accessible.')+`<section class="card"><h2>${confirmed?'Confirmation received':pending?'Waiting for secure confirmation':'Ratios and mixtures'}</h2>${confirmed?'<p>Your eligible Quant sessions are available again. Unpurchased, unpublished and expired content stays protected.</p>':pending?'<p>Your response has been sent. A browser success message alone cannot unlock content. Other Quant sessions stay paused until the verified notification arrives.</p>':` ${s.route==='live'?`<div class="field"><label>Did you attend the live class?</label><label class="row"><input type="radio" name="attendance" value="yes"> I attended</label><label class="row"><input type="radio" name="attendance" value="no"> I didn’t attend</label></div>`:''}<div class="field"><label for="response">What helped you understand the topic?</label><textarea id="response" placeholder="Illustrative question; final form supplied by Ishan"></textarea></div><small>Non-attendance is a valid response. You do not need a recording to submit it.</small>`}<div class="row space">${confirmed?goButton('Continue learning','learning',true):pending?action('Simulate verified notification','confirm-feedback',true):action('Simulate form submission','submit-feedback',true)}${goButton('Return to current session','session')}</div></section>`+note('Tally form integration is future work. All submission and confirmation states here are simulated; no real feedback record or unlock is created.');}
function access(){return heading('My account','Your course access','Your current subjects and access period, in one place.')+`<section class="card"><h2>${s.owned.join(' + ')}</h2><p>${pill('Access active')}</p><p>Six-month access · ends 30 April 2027, 6:00 PM IST</p><p class="muted">Illustrative purchase history is retained after expiry. Course access is separate from eligible live-batch registration.</p>${goButton('Continue learning','learning',true)}</section>`+note('This is a fictional active account. Select the expired scenario in Design review to inspect membership expiry.');}
function expired(){return `<section class="card expire"><div class="symbol">◷</div><div class="eyebrow">Membership access</div><h1>Your access has expired.</h1><p class="muted">Your six-month Full Course access ended on 31 October 2026. Protected readings, recordings, worksheets and live joins are no longer available.</p>${pill('Expired','amber')}<div class="history"><h3>Your history is preserved</h3><p>Full Course · Quant + Verbal + DI<br><small>Purchase and feedback history remain on your account.</small></p></div></section>`+note('A quiet notice with no renewal or purchase CTA, as requested. Expiry is authoritative; completing feedback cannot extend access.');}
function editor(){return heading('Admin / course publishing','Session configuration','Set up the reusable session once. Schedule actual live classes later in Batch publishing.',pill('Draft','gray'))+`<section class="card"><div class="grid three"><div class="field"><label for="offering">Offering</label><select id="offering">${['Full Course','Individual Quant','Individual Verbal','Individual DI'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="session-title">Session heading</label><input id="session-title" value="Quant 4 · Ratios and mixtures"></div><div class="field"><label>Course session date</label><p class="muted">Not required · undated content</p></div></div><details class="accordion" open><summary>01 · Pre-class read <small>Meaningful title and reading source</small></summary><div class="grid two"><div class="field"><label for="pre-title">Student-facing reading title</label><input id="pre-title" value="${esc(s.title)}"></div><div class="field"><label for="pre-source">Notion or content source</label><input id="pre-source" value="Illustrative reading draft"></div></div></details><details class="accordion"><summary>02 · Recording <small>Choose one shared recording</small></summary><div class="field"><label for="recording">Shared asset</label><select id="recording"><option>Quant 4 · Ratios and mixtures · Shared asset</option></select></div><p>Referenced by Individual Quant, Full Course and applicable live batches. No per-batch upload.</p></details><details class="accordion"><summary>03 · Post-class read <small>Independent title and source</small></summary><div class="field"><label for="post-title">Student-facing reading title</label><input id="post-title" value="${esc(s.post)}"></div></details><details class="accordion"><summary>04 · Worksheet <small>Session material and practice</small></summary><div class="field"><label for="worksheet-title">Worksheet title</label><input id="worksheet-title" value="Ratios: guided practice and worked answers"></div></details><details class="accordion"><summary>Additional placement options <small>Optional content outside the four-item session</small></summary><p>Before the course area · top of the course area · before a video · after a video · after the course area. Each reading keeps its own title, source, order and publication status.</p></details><div class="sticky-actions"><small>Broad outline follows the published offering automatically.</small><div class="actions">${action('Preview as student','preview-session')}${action('Save draft · demo','save-draft',true)}</div></div></section>`+note('Primary Admin navigation has two publishing destinations. Scope confirmation remains a deliberate final step, not another permanent sidebar item.');}
function batch(){return heading('Admin / course publishing','Batch publishing','Choose the offering, arrange the outline and schedule actual live classes.',goButton('Preview & publish','scope',true))+`<div class="grid split"><section class="card"><div class="grid two"><div class="field"><label for="batch-name">Batch name</label><input id="batch-name" value="November evening"></div><div class="field"><label for="batch-offering">Offering</label><select id="batch-offering"><option>Full Course · Quant + Verbal + DI</option><option>Individual Quant</option><option>Individual Verbal</option><option>Individual DI</option></select></div></div><table class="table"><thead><tr><th>Outline entry</th><th>Type</th><th>Schedule · IST</th></tr></thead><tbody><tr><td>Course orientation</td><td>Content</td><td>Undated</td></tr><tr><td>Quant 4 · Ratios</td><td>Actual live class</td><td>${s.date} · ${s.time}<br>${action('Open calendar','calendar')}</td></tr><tr><td>Mock review</td><td>Content</td><td>Undated</td></tr><tr><td>Practice / break</td><td>Outline note</td><td>Undated</td></tr></tbody></table><div class="notice space"><strong>Dates are for live events</strong><p>Non-live sessions, mock-review content and break notes may remain undated. If a mock review is an actual live meeting, schedule that event explicitly.</p></div></section><aside class="card"><h2>Before publishing</h2><p>${pill(s.published?'Published':'Draft',s.published?'':'gray')}</p><ul><li>Broad outline publishes with the offering</li><li>Live registration capacity: 8</li><li>Shared recording references preserved</li><li>Private Meet links excluded from public preview</li></ul><p class="muted">Editing November does not move December’s schedule.</p><details><summary>Class status and support</summary><p>Class completed, recording published, feedback confirmed and attendance self-report remain independent.</p>${action('Review completion · demo','completion')}</details></aside></div>`+note('No redundant Live classes Admin destination. Live dates and optional Meet details live inside Batch publishing.');}
function scope(){return heading('Admin / batch publishing','Review once. Publish with confidence.','Check the exact affected offerings and placements before confirming.',goButton('Back to draft','batch'))+`<div class="grid split"><section class="card"><h2>November evening · Full Course</h2><div class="field"><label for="scope">Publication scope</label><select id="scope"><option>This batch and its offering outline</option><option>Universal · all applicable Quant placements</option></select></div><div class="scope-list" id="scope-list"><strong>Affected scope</strong><ul><li>November evening batch</li><li>Full Course broad outline</li><li>Published Quant 4 session references</li></ul></div><div class="status-list"><span>Live event: ${s.date} · ${s.time} IST</span><span>Registration: 8 maximum</span></div><p>Protected material retains its own publication controls. Publishing does not grant access, claim attendance or create a recording.</p><label class="row"><input id="confirm-scope" type="checkbox"> I checked the content, schedule and affected scope.</label><div class="actions space">${action(s.published?'Confirm unpublish':'Confirm publish','publish',true)}${action('Student preview','preview-session')}</div></section><aside class="card"><h2>Student-facing order</h2><ol><li>${esc(s.title)}</li><li>Ratios and mixtures · recording</li><li>${esc(s.post)}</li><li>Guided practice · worksheet</li></ol><p>Unpublishing removes the selected published scope and retains the draft and audit history.</p></aside></div>`+note('The scope selector expands the target preview before confirmation. All writes remain local simulations.');}
function decisions(){return heading('Review notes','What changed, and what still needs a decision.','This prototype is a design deliverable; it does not claim future features are active in the LMS.')+`<div class="grid three"><section class="card"><h2>Three tiers, four offerings</h2><p>The annotated PDF asks for three package choices. The Phase 1 exit gate retains four offerings.</p><p>Resolved in this design: 1 / 2 / 3 individual-subject package tiers, plus a clearly distinct Full Course option.</p></section><section class="card"><h2>Feedback trigger</h2><p>The annotated PDF proposes an <strong>80% watched</strong> threshold. This is recorded for owner confirmation, not implemented as a new policy.</p><p>A section lock prevents more recording navigation; delayed live completion events may still create multiple obligations.</p></section><section class="card"><h2>Class corrections</h2><p>Completion reversal needs a rule for existing feedback locks. Preserve submissions and audit history.</p><p>The prototype does not invent an automatic unlock or claim a completed class proves attendance.</p></section></div><section class="notice space"><strong>Phase boundaries</strong><p>Phase 1 catalogue/access screens are separately deployed in Preview. Batch scheduling/publication belong to Phase 2; checkout to Phase 3; resume and feedback-gated learning delivery to Phase 4. This offline design changes none of those backend states.</p></section>`;}
function modalContent(kind){if(kind==='calendar'){const draft=s.calendarDraft||s;const day=Number(draft.date.slice(-2));return `<div class="modal-heading"><div><div class="eyebrow">November evening / Quant 4</div><h2 id="modal-title">Schedule an actual live class</h2></div>${action('×','close-modal',false,'aria-label="Close calendar"')}</div><div class="row between"><span class="calendar-caption">November 2026</span>${pill('Asia/Kolkata · IST','gray')}</div><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span>${d}</span>`).join('')}${Array.from({length:6},()=>'<button class="empty" tabindex="-1" disabled></button>').join('')}${Array.from({length:30},(_,i)=>`<button data-day="${i+1}" class="${day===i+1?'chosen':''}" aria-label="${i+1} November 2026" aria-pressed="${day===i+1}">${i+1}</button>`).join('')}</div><div class="grid two"><div class="field"><label for="calendar-date">Selected date</label><input id="calendar-date" type="date" value="${draft.date}"></div><div class="field"><label for="calendar-time">Start time · IST</label><input id="calendar-time" type="time" value="${draft.time}"></div></div><div class="field"><label for="private-meet">Google Meet link · optional, private</label><input id="private-meet" placeholder="meet.google.com/… (demo only)"></div><div class="actions">${action('Save date to draft','save-calendar',true)}${action('Cancel','close-modal')}</div><p><small>Only this November live event changes. December and undated course content stay independent.</small></p>`;}const target=s.upgrade||'Verbal';const oldCount=s.owned.length;const newCount=Math.min(3,oldCount+1);const diff=prices[newCount]-prices[oldCount];return `<div class="modal-heading"><div><div class="eyebrow">Add a subject</div><h2 id="modal-title">Unlock ${target} when you’re ready.</h2></div>${action('×','close-modal',false,'aria-label="Close upgrade"')}</div><p>You currently have ${s.owned.join(' + ')}. Add ${target} to explore its full curriculum.</p><div class="notice"><div class="row between"><span>Current individual package</span><strong>${money(prices[oldCount])}</strong></div><div class="row between"><span>${newCount}-subject individual package</span><strong>${money(prices[newCount])}</strong></div><div class="row between space"><strong>Upgrade difference</strong><strong>${money(diff)}</strong></div></div><p class="muted">Your existing ${s.owned.join(' + ')} access stays available. An upgrade is granted only after successful payment.</p><div class="actions">${action('Review upgrade','review-upgrade',true)}${action('Keep learning','close-modal')}</div><p><small>Illustrative quote; the real server must verify purchase eligibility and expiry. Individual packages remain distinct from Full Course.</small></p>`;}
const screens={catalogue,detail,learning,live,session,feedback,access,expired,editor,batch,scope,decisions};
function shell(){return `<div class="shell">${nav()}<main id="content" tabindex="-1">${screens[s.screen]()}${s.modal?`<section class="modal-static" data-print-modal="${s.modal}">${modalContent(s.modal)}</section>`:''}</main></div>`;}
function render(){const modal=s.modal;s.modal='';$('#app').innerHTML=shell();s.modal=modal;if(modal)showModal(modal);}
function showModal(kind){if(kind==='calendar'&&!s.calendarDraft)s.calendarDraft={date:s.date,time:s.time};s.modal=kind;const el=$('#modal');el.innerHTML=modalContent(kind);if(!el.open)el.showModal();}
function closeModal(){s.modal='';delete s.calendarDraft;$('#modal').close();}
function load(id){const row=scenarios.find(x=>x[0]===id)||scenarios[0];s={...state(),...row[2],selected:[...(row[2].selected||['Quant'])],owned:[...(row[2].owned||subjects)]};$('#scenario').value=row[0];if($('#modal').open)$('#modal').close();render();}
function go(screen){if(s.expired&&['learning','session','live'].includes(screen)){screen='expired';}s.role=['editor','batch','scope'].includes(screen)?'admin':'student';s.screen=screen;closeModal();render();window.scrollTo(0,0);}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function capture(){s.title=$('#pre-title')?.value||s.title;s.post=$('#post-title')?.value||s.post;}
const actions={
 mocks:()=>toast('Mocks are unchanged by this design.'),
 'review-package':()=>{delete s.upgradeQuote;s.offering=s.selected.join(' + ')+' individual package';go('detail');},
 'full-course':()=>{delete s.upgradeQuote;s.offering='Full Course';go('detail');},
 'checkout':()=>toast('Payment is future Phase 3 work. No account, purchase or grant was created.'),
 'sample-session':()=>{s.subject='Quant';s.session=4;go('session');},
 resume:()=>{s.session=s.subject==='Quant'?4:1;go('session');},
 outline:()=>{s.offering='Full Course';go('detail');},
 meet:()=>toast('Eligible Quant live join simulated. No external meeting opens.'),
 worked:()=>toast('Worked example: five parts of 100 ml = 200 ml concentrate + 300 ml water.'),
 worksheet:()=>toast('Worksheet preview simulated; no file or progress change.'),
 'submit-feedback':()=>{s.feedback='pending';render();},
 'confirm-feedback':()=>{s.feedback='confirmed';s.locked=false;render();},
 'preview-session':()=>{capture();s.subject='Quant';s.session=4;go('session');toast('Draft student preview only. Nothing published; feedback and progress unchanged.');},
 'save-draft':()=>{capture();toast('Draft retained in this tab only. Nothing saved to the LMS.');},
 calendar:()=>showModal('calendar'),
 'close-modal':closeModal,
 'save-calendar':()=>{const date=$('#calendar-date').value;const time=$('#calendar-time').value;if(!date||!time){toast('Choose a date and start time for this actual live event.');return;}s.date=date;s.time=time;closeModal();render();toast('Live event draft updated locally. Other batches and content are unchanged.');},
 'review-upgrade':()=>{s.selected=[...s.owned,s.upgrade||'Verbal'];s.tier=s.selected.length;s.upgradeQuote={existing:prices[s.owned.length],total:prices[s.tier],difference:prices[s.tier]-prices[s.owned.length]};s.offering=s.selected.join(' + ')+' individual package';go('detail');},
 completion:()=>toast('Completion records the class status only, never individual attendance. Support correction is separate.'),
 publish:()=>{if(!$('#confirm-scope').checked){toast('Confirm the listed content, schedule and scope first.');return;}s.published=!s.published;render();toast(s.published?'Publication simulated. No LMS records changed.':'Unpublication simulated. Draft history is retained.');}
};
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.screen){e.preventDefault();go(el.dataset.screen);}else if(el.dataset.action){e.preventDefault();actions[el.dataset.action]?.();}else if(el.dataset.route){s.route=el.dataset.route;render();}else if(el.dataset.tier){s.tier=Number(el.dataset.tier);s.selected=s.selected.slice(0,s.tier);if(s.tier===3)s.selected=[...subjects];render();}else if(el.dataset.subject){if(!s.owned.includes(el.dataset.subject)){s.upgrade=el.dataset.subject;showModal('upsell');}else{s.subject=el.dataset.subject;render();}}else if(el.dataset.session){s.session=Number(el.dataset.session);go('session');}else if(el.dataset.day){s.calendarDraft={date:'2026-11-'+el.dataset.day.padStart(2,'0'),time:$('#calendar-time').value||s.time};showModal('calendar');}});
document.addEventListener('change',e=>{if(e.target.id==='scenario')load(e.target.value);if(e.target.dataset.subjectChoice){const sub=e.target.dataset.subjectChoice;if(e.target.checked){if(s.selected.length===s.tier){e.target.checked=false;toast('Choose a larger package to select another subject.');return;}s.selected.push(sub);}else s.selected=s.selected.filter(x=>x!==sub);render();}if(e.target.id==='scope'){$('#scope-list').innerHTML=e.target.selectedIndex?'<strong>Universal scope · affected references</strong><ul><li>Individual Quant → Quant 4</li><li>Full Course → Quant 4</li><li>November Quant batch → Quant 4</li><li>December Quant batch → Quant 4</li></ul><small>One shared item. Verbal and DI are unaffected.</small>':'<strong>Affected scope</strong><ul><li>November evening batch</li><li>Full Course broad outline</li><li>Published Quant 4 session references</li></ul>';$('#confirm-scope').checked=false;}});
$('#modal').addEventListener('cancel',()=>{s.modal='';delete s.calendarDraft;});
$('#scenario').innerHTML=scenarios.map(([id,label])=>`<option value="${id}">${label}</option>`).join('');
if(new URLSearchParams(location.search).has('print')){document.body.classList.add('print-mode');$('#app').innerHTML=`<section class="print-cover"><div class="eyebrow">ACE CLUB LMS V2 · 01 NOVEMBER 2026</div><h1>A simpler way to teach.<br>A clearer place to learn.</h1><p>Revised wireframes incorporating Ishan’s annotated review and discussion notes.</p><p>18 review screens · Course packages, learning states and Admin publishing</p><p class="small">Design prototype only. Fictional data and simulated interactions.<br>Production, Preview configuration, migrations and student data are unchanged.<br>Open index.html for clickable selectors, calendar and upgrade dialogs.</p></section>`+scenarios.map(([id,label,values],i)=>{s={...state(),...values};return `<article class="print-page" data-print-screen="${id}"><div class="print-label">${String(i+1).padStart(2,'0')} / ${label.slice(5)} · DESIGN PROPOSAL</div>${shell()}</article>`;}).join('');}else load(new URLSearchParams(location.search).get('scenario')||'catalogue');
